static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GooglenetInceptionV1CustomTilingData tiling;

    uint32_t len0 = static_cast<uint32_t>(context->GetInputShape(0)->GetOriginShape().GetShapeSize());
    uint32_t len1 = static_cast<uint32_t>(context->GetInputShape(1)->GetOriginShape().GetShapeSize());
