at::Tensor googlenet_inception_v1_custom_impl_npu(const at::Tensor& b1, const at::Tensor& b3,
                                                  const at::Tensor& b5, const at::Tensor& bp) {
    // 输出张量形状由框架推断并传入，按通道拼接
    TORCH_CHECK(b1.dtype() == at::kFloat, "Only float32 is supported");
    at::IntArrayRef s0 = b1.sizes();
    TORCH_CHECK(b3.sizes()[0] == s0[0] && b3.sizes()[2] == s0[2] && b3.sizes()[3] == s0[3], "Input shapes mismatch");
    TORCH_CHECK(b5.sizes()[0] == s0[0] && b5.sizes()[2] == s0[2] && b5.sizes()[3] == s0[3], "Input shapes mismatch");
    TORCH_CHECK(bp.sizes()[0] == s0[0] && bp.sizes()[2] == s0[2] && bp.sizes()[3] == s0[3], "Input shapes mismatch");

    int64_t C = b1.size(1) + b3.size(1) + b5.size(1) + bp.size(1);
    at::Tensor out = at::empty({s0[0], C, s0[2], s0[3]}, b1.options());

